SELECT * FROM tw_watermark_resource_log
WHERE team_id = #{teamId}

    AND event_type = #{eventType}


    AND resource_scope = #{resourceScope}


    AND resource_name LIKE CONCAT('%', #{resourceName}, '%')


    AND operator_username LIKE CONCAT('%', #{operatorKeyword}, '%')


    AND created_at  >=  #{startTime}


    AND created_at  <=  #{endTime}

ORDER BY created_at DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM tw_watermark_resource_log
WHERE team_id = #{teamId}

    AND event_type = #{eventType}


    AND resource_scope = #{resourceScope}


    AND resource_name LIKE CONCAT('%', #{resourceName}, '%')


    AND operator_username LIKE CONCAT('%', #{operatorKeyword}, '%')


    AND created_at  >=  #{startTime}


    AND created_at  <=  #{endTime}
